import {icon} from './icons.js';
import {areaGearLevel} from './location-schema.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kindName={field:'野外挂机',dungeon:'普通副本',boss:'首领副本'};
export function renderLegacyHandoff(migration){if(migration?.legacyDrain)return '<div class="legacyJourneyNotice"><b>旧旅程正在收尾</b><span>保留当前敌人与已得收获；完成这场战斗或本次副本后停止，请重新选择新区域。</span><button data-view="battle">继续当前旅程</button></div>';if(migration?.reselectRequired)return '<div class="legacyJourneyNotice"><b>请选择新的冒险地点</b><span>旧存档和背包均已保留，不会自动前往更强的区域。</span></div>';return '';}
export function renderDwarfRegion(nodes,{selectedArea=1,sourceFocus=null,migration=null,highestUnlocked=1,now=Date.now()}={}){
 const areaNodes=nodes.filter(n=>n.areaNumber===selectedArea),areas=[...new Set(nodes.map(n=>n.areaNumber).filter(Number.isInteger))].sort((a,b)=>a-b).map(number=>{const rows=nodes.filter(n=>n.areaNumber===number),first=rows[0];return {number,name:first?.name?.split(' · ')[0]||`区域 ${number}`,rows,unlocked:rows.some(n=>n.unlocked),range:first?.levelRange||[(number-1)*10+1,number*10]};});
 return renderLegacyHandoff(migration)+`<div class="viewport dwarfRegionViewport"><canvas class="mapCanvas" id="regionCanvas" width="960" height="540" aria-label="矮人已开放区域地图"></canvas><div class="dwarfAreaPins">${areas.map((a,i)=>`<button class="territoryPin dwarfAreaPin ${a.number===selectedArea?'selected':''} ${a.unlocked?'playable':'locked'}" style="left:${areas.length>6?12+i%4*25:15+i%3*35}%;top:${areas.length>6?22+Math.floor(i/4)*29:areas.length>3?32+Math.floor(i/3)*37:[61,53,36][i]}%" data-planned-area="${a.number}" aria-pressed="${a.number===selectedArea}"><span class="nodeIcon">${icon(['forge','ore','fire'][(a.number-1)%3])}</span><b>${esc(a.name)}</b><small>第${a.number}区域 · 推荐 ${a.range[0]}–${a.range[1]}级${a.unlocked?'':' · 未解锁'}</small></button>`).join('')}</div><div class="mapCorner"><span>矮人 · 独立探索进度</span><strong>黑炉山脉</strong></div><div class="mapHint">普通副本通关后解锁下一区域 · 推荐等级不是进入限制</div></div><div class="plannedNodeTray" aria-label="第${selectedArea}区域地点">${areaNodes.map(n=>{const remaining=Math.max(0,Math.ceil((n.readyAt-now)/1000)),base=areaGearLevel(n.id),gearRange=Number.isFinite(base)?` · 装备Lv.${Math.max(n.levelRange[0],base-2)}–${Math.min(n.levelRange[1],base+2)}`:'';return `<button class="plannedNode ${n.kind} ${sourceFocus===n.id?'sourceFocused':''}" data-planned-node="${esc(n.id)}" ${!n.unlocked?'disabled':''}><span>${icon(n.kind==='boss'?'shield':n.kind==='dungeon'?'sword':'ore')}</span><b>${esc(n.name)}</b><small>${kindName[n.kind]}${n.kind==='dungeon'?' · 连续3场':n.kind==='boss'?' · 手动挑战':''}${gearRange}</small><em>${!n.unlocked?'先通关前一区域普通副本':!n.budgetReady?'配置准备中 · 暂不可出发':remaining?'冷却 '+Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0'):'可选择'}</em></button>`;}).join('')}</div><div class="futureAreaTrack" aria-label="后续规划区域">${Array.from({length:Math.max(0,10-areas.length)},(_,i)=>`<span>区域 ${i+areas.length+1}<small>${i+areas.length+1<=highestUnlocked?'已解锁 · 待开放':'尚未开放'}</small></span>`).join('')}</div>`;
}
export function renderPlannedRoute(nodes,state,{encounter=null,now=Date.now(),resting=false}={}){
 if(state.contentMigration?.legacyDrain)return renderLegacyHandoff(state.contentMigration);
 const route=state.expedition||{},selected=nodes.find(n=>n.id===route.targetInstanceId)||nodes.find(n=>n.id===route.fieldId),normal=nodes.find(n=>n.areaNumber===(selected?.areaNumber||1)&&n.kind==='dungeon'),fields=nodes.filter(n=>n.kind==='field'&&n.unlocked),left=Math.max(0,Math.ceil(((normal?.readyAt??0)-now)/1000));
 return `<div class="expeditionControls"><div><strong>${state.dungeonRun?esc(normal?.name||'普通副本')+' · 第'+state.dungeonRun.stage+'/3场':route.mode==='dungeon'?'普通副本计划':'野外挂机'}</strong><small>选择已解锁地点，首领只手动挑战</small></div><label>冷却期挂机点 <select id="fallbackField">${fields.map(n=>`<option value="${esc(n.id)}" ${route.fieldId===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><button data-dungeonloop="1" aria-pressed="${!!route.loop}" ${!normal?'disabled':''}>${route.loop?'✓':'○'} 循环普通副本</button><button data-planned-node="${esc(normal?.id||'')}" data-planned-start="1" id="dungeonBtn" ${!normal?.unlocked||!normal?.budgetReady||left||encounter&&!encounter.done||state.dungeonRun||resting?'disabled':''}>${left?'副本冷却 '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0'):'挑战普通副本 · 3场'}</button><p class="subtleText">场间生命、技能冷却与自身状态延续；护佑和涅槃按每小战计算。途中收获保留，失败从第1场重来。普通副本通关冷却5分钟；循环时回所选野外，冷却结束再挑战。首领通关冷却30分钟。</p></div>`;
}
